import type { EngineInterface, Register } from 'claude-code'

export type Metadata = Record<string, string>

export function parseCommand(prompt: string): { skill: string; args: string } | undefined {
  const match = /^\s*\/([A-Za-z0-9_.-]+)(?:\s+([\s\S]*))?$/.exec(prompt)
  return match ? { skill: match[1], args: (match[2] ?? '').trim() } : undefined
}

function unquote(raw: string): string {
  const value = raw.trim()
  const double = /^"((?:[^"\\]|\\.)*)"\s*(?:#.*)?$/.exec(value)
  if (double) return double[1].replace(/\\(.)/g, (_, c: string) => ({ n: '\n', t: '\t' })[c] ?? c)
  const single = /^'((?:[^']|'')*)'\s*(?:#.*)?$/.exec(value)
  if (single) return single[1].replace(/''/g, "'")
  return value.replace(/\s+#.*$/, '')
}

export function parseMetadata(skillMd: string): Metadata {
  const front = /^---\r?\n([\s\S]*?)\r?\n---\s*(?:\r?\n|$)/.exec(skillMd)
  const metadata: Metadata = {}
  if (!front) return metadata
  let inside = false
  for (const line of front[1].split(/\r?\n/)) {
    if (/^metadata:\s*$/.test(line)) { inside = true; continue }
    if (!inside || line.trim() === '' || /^\s*#/.test(line)) continue
    if (!/^\s/.test(line)) break
    const pair = /^\s+([A-Za-z0-9_-]+):\s*(.*)$/.exec(line)
    if (pair) metadata[pair[1]] = unquote(pair[2])
  }
  return metadata
}

const FILTERS = new Map<string, (value: string) => string>([
  ['lower', (value) => value.toLowerCase()],
  ['basename', (value) => {
    const path = value.replace(/[?#].*$/, '').replace(/\/+$/, '')
    return path.slice(path.lastIndexOf('/') + 1)
      .replace(/\.(git|deb|rpm|AppImage|tar\.[a-z0-9]+|tgz|zip)$/i, '')
  }],
])

export function render(template: string, values: Record<string, string | undefined>): string | undefined {
  let complete = true
  const text = template.replace(/\{([^{}|]*)((?:\|[^{}|]*)*)\}/g, (_, name: string, filters: string) => {
    const key = name.trim()
    let value = Object.prototype.hasOwnProperty.call(values, key) ? values[key] : undefined
    for (const filter of filters.split('|').slice(1)) {
      const apply = FILTERS.get(filter.trim())
      if (apply === undefined || value === undefined) { value = undefined; break }
      value = apply(value)
    }
    if (!value) complete = false
    return value ?? ''
  })
  return complete ? text : undefined
}

function compile(pattern: string): RegExp | undefined {
  try {
    return new RegExp(pattern)
  } catch {
    return undefined
  }
}

export function titleFor(metadata: Metadata, skill: string, args: string, now: Date): string | undefined {
  const day = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}`
  const base: Record<string, string | undefined> = { skill, args, date: day }
  const words = args === '' ? [] : args.split(/\s+/)
  const positional = (list: readonly (string | undefined)[]) =>
    Object.fromEntries(list.map((value, i) => [String(i + 1), value]))

  const template = metadata['skill-session-mods-title']
  const fallback = metadata['skill-session-mods-title-fallback']
  const condition = metadata['skill-session-mods-title-apply-if-match']
  let title: string | undefined
  if (template !== undefined) {
    if (condition === undefined) {
      title = render(template, { ...positional(words), ...base })
    } else {
      const match = compile(condition)?.exec(args)
      if (match) title = render(template, { ...positional(match.slice(1)), ...base })
    }
  }
  if (title === undefined && fallback !== undefined) title = render(fallback, { ...positional(words), ...base })
  return title
}

async function projectDirs($: EngineInterface): Promise<string[]> {
  const dirs: string[] = []
  let dir = await $.session.cwd()
  for (;;) {
    dirs.push(dir)
    if (await $.fs.exists(`${dir}/.git`)) return dirs
    const last = dir.startsWith('/') ? /\/[^/]*$/ : /[\\/][^\\/]*$/
    const parent = dir.replace(last, '') || '/'
    if (parent === dir) break
    dir = parent
  }
  return dirs
}

async function readMetadata($: EngineInterface, skill: string): Promise<Metadata | undefined> {
  const home = await $.env.get('HOME')
  const personal = home === undefined ? undefined : `${home}/.claude/skills/${skill}/SKILL.md`
  if (personal !== undefined && await $.fs.exists(personal)) return parseMetadata(await $.fs.read(personal))
  for (const dir of (await projectDirs($)).reverse()) {
    const path = `${dir === '/' ? '' : dir}/.claude/skills/${skill}/SKILL.md`
    if (await $.fs.exists(path)) return parseMetadata(await $.fs.read(path))
  }
  return undefined
}

function colorize($: EngineInterface, color: string): void {
  $.clock.after(0, () => {
    $.command.run({ command: 'color', args: color }).catch((err: unknown) => $.ui.log(String(err)))
  })
}

export const register: Register = (on) => {
  let pendingColor: string | undefined

  on('classic.UserPromptSubmit', async ($, e, next) => {
    const result = await next(e)
    const command = parseCommand(e.prompt)
    if (command === undefined) return result
    try {
      const metadata = await readMetadata($, command.skill)
      if (metadata === undefined) return result
      if (metadata['skill-session-mods-color']) pendingColor = metadata['skill-session-mods-color']
      const condition = metadata['skill-session-mods-title-apply-if-match']
      if (condition !== undefined && compile(condition) === undefined) {
        $.ui.log(`${command.skill}: invalid skill-session-mods-title-apply-if-match: ${condition}`)
      }
      const title = titleFor(metadata, command.skill, command.args, new Date(await $.clock.now()))
      return title ? { ...result, sessionTitle: title } : result
    } catch (err) {
      $.ui.log(`${command.skill}: ${String(err)}`)
      return result
    }
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined && pendingColor !== undefined) {
      const color = pendingColor
      pendingColor = undefined
      colorize($, color)
    }
    return result
  })
}

